import re
from typing import Union, List, Tuple

Number = Union[int, float]

class Token:
    def __init__(self, type_: str, value: Number):
        self.type = type_
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

def tokenize(expr: str) -> List[Token]:
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        c = expr[i]

        if c.isspace():
            i += 1
            continue

        if c in '+-*/%()':
            tokens.append(Token(c, c))
            i += 1
        elif c.isdigit() or (c == '.' and i+1 < n and expr[i+1].isdigit()):
            start = i
            while i < n and (expr[i].isdigit() or expr[i] == '.'):
                i += 1
            num_str = expr[start:i]
            if '.' in num_str:
                tokens.append(Token('NUMBER', float(num_str)))
            else:
                tokens.append(Token('NUMBER', int(num_str)))
        else:
            raise ValueError(f"Invalid character: {c}")

    return tokens

def parse_unary(tokens: List[Token], pos: int) -> Tuple[Token, int]:
    if pos >= len(tokens):
        raise ValueError("Unexpected end of expression")

    if tokens[pos].type in ('+', '-'):
        op = tokens[pos]
        pos += 1
        right, pos = parse_term(tokens, pos)
        return Token('UNARY', op.value), pos
    else:
        return parse_term(tokens, pos)

def parse_term(tokens: List[Token], pos: int) -> Tuple[Token, int]:
    left, pos = parse_unary(tokens, pos)

    while pos < len(tokens) and tokens[pos].type in ('*', '/', '%'):
        op = tokens[pos]
        pos += 1
        right, pos = parse_unary(tokens, pos)

        if op.type == '*':
            left = left.value * right.value
        elif op.type == '/':
            if right.value == 0:
                raise ValueError("Division by zero")
            left = left.value / right.value
        elif op.type == '%':
            if right.value == 0:
                raise ValueError("Modulo by zero")
            left = left.value % right.value

    return Token('TERM', left), pos

def parse_power(tokens: List[Token], pos: int) -> Tuple[Token, int]:
    left, pos = parse_term(tokens, pos)

    while pos < len(tokens) and tokens[pos].type == '**':
        op = tokens[pos]
        pos += 1
        right, pos = parse_unary(tokens, pos)
        left = right.value ** left.value  # Right associative

    return Token('POWER', left), pos

def parse_additive(tokens: List[Token], pos: int) -> Tuple[Token, int]:
    left, pos = parse_power(tokens, pos)

    while pos < len(tokens) and tokens[pos].type in ('+', '-'):
        op = tokens[pos]
        pos += 1
        right, pos = parse_power(tokens, pos)

        if op.type == '+':
            left = left.value + right.value
        else:
            left = left.value - right.value

    return Token('ADDITIVE', left), pos

def evaluate(expr: str) -> Number:
    tokens = tokenize(expr)
    if not tokens:
        raise ValueError("Empty expression")

    result, pos = parse_additive(tokens, 0)

    if pos != len(tokens):
        raise ValueError(f"Unexpected token: {tokens[pos]}")

    return result.value
