        op = tokens[pos]
        pos += 1
        right, pos = parse_unary(tokens, pos)
        left = right.value ** left.value  # Right associative

    return Token('POWER', left), pos

def parse_additive(tokens: List[Token], pos: int) -> Tuple[Token, int]:
    left, pos = parse_power(tokens, pos)

    while pos < len(tokens) and tokens[pos].type in ('+', '-'):
        op = tokens[pos]
        pos += 1
        right, pos = parse_power(tokens, pos)

        if op.type == '+':
            left = left.value + right.value
        else:
            left = left.value - right.value

    return Token('ADDITIVE', left), pos

