    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []
        self.snapshots = []
        self.current_snapshot = 0

    def find(self, x):
        root = x
        while self.parent[root] != root:
            root = self.parent[root]
        return root

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)

        if root_a == root_b:
            return False

        if self.size[root_a] < self.size[root_b]:
            root_a, root_b = root_b, root_a

        self.parent[root_b] = root_a
        self.size[root_a] += self.size[root_b]

        self.history.append((root_b, root_a, self.size[root_a] - self.size[root_b]))
        return True

    def snapshot(self):
        self.snapshots.append(len(self.history))
        self.current_snapshot = len(self.snapshots) - 1
        return self.current_snapshot

