        to_rollback = len(self.history) - target_index

        for _ in range(to_rollback):
            child, parent, old_size = self.history.pop()
            self.parent[child] = child
            self.size[parent] -= self.size[child]

    def components(self):
        return sum(1 for i in range(len(self.parent)) if self.parent[i] == i)

