def to_base(n, alphabet):
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")
    if len(alphabet) != len(set(alphabet)):
        raise ValueError("Alphabet must contain distinct characters")
    if alphabet[0] != '0':
        raise ValueError("First character of alphabet must be '0'")

    if n == 0:
        return alphabet[0]

    negative = n < 0
    n = abs(n)
    base = len(alphabet)
    digits = []

    while n > 0:
        n, remainder = divmod(n, base)
        digits.append(alphabet[remainder])

    result = ''.join(reversed(digits))
    return '-' + result if negative else result


def from_base(s, alphabet):
    if not s:
        raise ValueError("String cannot be empty")

    if len(alphabet) != len(set(alphabet)):
        raise ValueError("Alphabet must contain distinct characters")
    if alphabet[0] != '0':
        raise ValueError("First character of alphabet must be '0'")

    base = len(alphabet)
    digit_map = {char: i for i, char in enumerate(alphabet)}

    negative = False
    if s.startswith('-'):
        negative = True
        s = s[1:]
        if not s:
            raise ValueError("String cannot be empty after sign")

    for char in s:
        if char not in digit_map:
            raise ValueError(f"Character '{char}' not in alphabet")

    value = 0
    for char in s:
        value = value * base + digit_map[char]

    return -value if negative else value
