module.exports = function zipLongest(fill, ...iterables) {
  if (iterables.length === 0) {
    return (function* () {})();
  }

  const iterators = iterables.map(it => {
    const iter = typeof it[Symbol.iterator] === 'function' ? it[Symbol.iterator]() : it;
    return { iter, done: false };
  });

  return (function* () {
    while (true) {
      const row = [];
      const activeCount = iterators.length;
      let hasActive = false;

      for (let i = 0; i < activeCount; i++) {
        const { iter, done } = iterators[i];
        if (!done) {
          hasActive = true;
          try {
            const value = iter.next();
            if (value.done) {
              iterators[i].done = true;
              row.push(fill);
            } else {
              row.push(value.value);
            }
          } catch (e) {
            iterators[i].done = true;
            row.push(fill);
          }
        } else {
          row.push(fill);
        }
      }

      if (!hasActive) {
        break;
      }

      yield row;
    }
  })();
};

