module.exports = function memoize(fn, keyFn) {
  const calls = { count: 0 };
  let cache = null;
  let isWeakMap = false;

  function getCacheKey(arg) {
    if (keyFn) {
      return keyFn(arg);
    }
    if (typeof arg === 'object' && arg !== null) {
      return arg;
    }
    return arg;
  }

  function getCachedCache() {
    if (cache) return cache;
    if (typeof fn === 'function' && keyFn) {
      cache = new Map();
    } else if (typeof fn === 'function') {
      cache = new Map();
      isWeakMap = true;
    }
    return cache;
  }

  function clearCache() {
    if (cache) {
      if (isWeakMap) {
        cache.clear();
      } else {
        cache = new Map();
      }
    }
  }

  return function memoized(...args) {
    const arg = args[0];
    const key = getCacheKey(arg);
    const cachedCache = getCachedCache();

    if (cachedCache.has(key)) {
      return cachedCache.get(key);
    }

    calls.count++;

    try {
      const result = fn.apply(this, args);
      if (cachedCache instanceof Map) {
        cachedCache.set(key, result);
      }
      return result;
    } catch (e) {
      // Do not cache throws
      throw e;
    }
  };
};

memoized.prototype = {
  get cache() {
    return getCachedCache();
  },
  get calls() {
    return calls.count;
  },
  clear() {
    clearCache();
  }
};

