module.exports = function sqlTag(strings, ...expressions) {
  let text = '';
  let values = [];
  let placeholderCounter = 0;

  const getPlaceholder = (val) => {
    if (val === undefined || val === null) return '';
    if (typeof val === 'string') return val;
    if (typeof val === 'number') return val;
    if (typeof val === 'boolean') return val ? '1' : '0';
    if (typeof val === 'object') {
      if (val.sqlTagResult) {
        // Inline nested sqlTag result
        return val.sqlTagResult.text;
      }
      if (Array.isArray(val)) {
        // Array becomes parenthesised comma-separated list
        const inner = val.map(getPlaceholder).join(', ');
        return `(${inner})`;
      }
      // Fallback for objects: stringify or handle as needed
      return JSON.stringify(val);
    }
    return String(val);
  };

  const addPlaceholder = (val) => {
    const placeholder = `$${placeholderCounter + 1}`;
    values.push(val);
    placeholderCounter++;
    return placeholder;
  };

  for (let i = 0; i < strings.length; i++) {
    const staticPart = strings[i];
    const dynamicPart = i < expressions.length ? expressions[i] : undefined;

    text += staticPart;

    if (dynamicPart !== undefined) {
      if (typeof dynamicPart === 'string' || typeof dynamicPart === 'number' || typeof dynamicPart === 'boolean') {
        // Simple values: inline directly if they are simple primitives, but the prompt implies placeholders for all interpolations
        // "each interpolation becomes a positional placeholder"
        text += addPlaceholder(dynamicPart);
      } else {
        // Complex values (objects, arrays, or nested sqlTag results)
        if (dynamicPart.sqlTagResult) {
          // Inline nested sqlTag result
          text += dynamicPart.sqlTagResult.text;
          // Merge values: we need to renumber placeholders in the nested text if we were to reference them,
          // but since we are inlining, the nested placeholders are already resolved to $1, $2 etc in the nested text.
          // However, the prompt says "placeholders renumbered". This implies if the nested text has $1, it should become $1 relative to the new context?
          // Actually, usually inlining means the nested query's parameters are flattened.
          // If nested text is "SELECT * FROM t WHERE a=$1", and we inline it, it becomes "SELECT * FROM t WHERE a=$1".
          // But if the outer query also has parameters, the $1 in the nested part might conflict if we just concatenate.
          // The prompt says: "its placeholders renumbered". This suggests we need to shift the indices of the nested placeholders
          // to start after the current count.
          const nestedValues = dynamicPart.sqlTagResult.values;
          const nestedText = dynamicPart.sqlTagResult.text;

          // We need to replace $1, $2... in nestedText with $(currentCount + 1), $(currentCount + 2)...
          // But wait, the prompt says "Repeated occurrences of the same value still get separate placeholders."
          // This applies to the top level. For inlining, if the nested query has $1 twice, they should probably remain distinct in the final output?
          // Or does "renumbered" mean we just shift the base index?
          // Let's assume we shift the base index of the nested placeholders to continue the sequence.
          // Example: Outer has $1. Nested has $1. Result should have $2 (for outer) and $3 (for nested's $1).
          // But the nested text is already generated. We need to transform the text.

          // Strategy: Replace $N in nestedText with $((currentCount + N))
          // We must be careful not to replace parts of strings that look like placeholders but aren't.
          // Assuming standard SQL tag usage, $ followed by digits.

          let shiftedText = nestedText;
          for (let n = 1; n <= nestedValues.length; n++) {
            const oldPlaceholder = `$${n}`;
            const newPlaceholder = `$${placeholderCounter + n}`;
            // Escape special regex chars in placeholder? No, $ and digits are safe.
            // But we must replace all occurrences.
            shiftedText = shiftedText.split(oldPlaceholder).join(newPlaceholder);
          }
          text += shiftedText;

          // Merge values: append nested values to our list
          values = values.concat(nestedValues);
          placeholderCounter += nestedValues.length;
        } else if (Array.isArray(dynamicPart)) {
          // Array becomes parenthesised comma-separated list of placeholders
          const inner = dynamicPart.map(addPlaceholder).join(', ');
          text += `(${inner})`;
        } else {
          // Object or other complex type: treat as a single value placeholder
          text += addPlaceholder(dynamicPart);
        }
      }
    }
  }

  return { text, values };
};

