export type Config = {
  name: string;
  age?: number;
  active: boolean;
};

export type BuilderState<T> = {
  config: Partial<T>;
  requiredKeys: Set<keyof T>;
  optionalKeys: Set<keyof T>;
  setKeys: Set<keyof T>;
};

export function builder<T extends Record<string, unknown>>() {
  const state: BuilderState<T> = {
    config: {} as Partial<T>,
    requiredKeys: new Set(Object.keys(T).filter((k) => {
      const prop = T as any;
      return prop[k] !== undefined && prop[k] !== null;
    }).map((k) => k as keyof T)),
    optionalKeys: new Set(Object.keys(T).filter((k) => {
      const prop = T as any;
      return prop[k] === undefined || prop[k] === null;
    }).map((k) => k as keyof T)),
    setKeys: new Set(),
  };

  const set = <K extends keyof T>(key: K, value: T[K]) => {
    if (!state.requiredKeys.has(key) && !state.optionalKeys.has(key)) {
      throw new Error(`Unknown key: ${key}`);
    }
    state.config[key] = value;
    state.setKeys.add(key);
    return set;
  };

  const build = () => {
    const missingRequired = state.requiredKeys.filter((k) => !state.setKeys.has(k));
    if (missingRequired.length > 0) {
      throw new Error(`Missing required keys: ${missingRequired.join(', ')}`);
    }
    return state.config as T;
  };

  return {
    set,
    build,
  };
}

export function builderConfig<T extends Config>() {
  return builder<T>();
}

