export type CurryableFn<T extends any[]> = (...args: T) => any;

export type Curry<T extends any[]> = {
  <R>(...args: T): R;
  <R>(arg: T[0], ...args: T extends [infer Head, ...infer Tail] ? Tail : never): Curry<T extends [infer Head, ...infer Tail] ? Tail : never>;
};

// Helper to extract the tail of a tuple
type Tail<T extends any[]> = T extends [any, ...infer Rest] ? Rest : never;

// Helper to extract the head of a tuple
type Head<T extends any[]> = T extends [infer First, ...any[]] ? First : never;

// Recursive curry implementation
type CurryImpl<T extends any[], Acc = never> = Acc extends any
  ? // Base case: no more arguments needed
    (args: T extends [] ? [] : never) => (Acc extends T ? Acc : never)
  : // Recursive case: take one argument
    (arg: Head<T>, ...restArgs: Tail<T>) => CurryImpl<Tail<T>, [...Acc, Head<T>]>;

// Public export: curry function
export function curry<T extends any[]>(fn: (...args: T) => any): Curry<T> {
  const originalFn = fn;
  const arity = fn.length;

  function helper(...args: any[]): any {
    if (args.length === arity) {
      return originalFn(...args);
    }
    return (...moreArgs: any[]) => helper(...args, ...moreArgs);
  }

  // Type assertion to ensure the helper matches the curry signature
  return helper as Curry<T>;
}

