export type Brand<T, B> = T & { readonly __brand: unique symbol & B };

export type Email = Brand<string, 'Email'>;

export function isEmail(s: string): s is Email {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s);
}

export function asEmail(s: string): Email {
  if (!isEmail(s)) {
    throw new Error(`Invalid email address: ${s}`);
  }
  return s as Email;
}

