    if (inProgress.has(name)) {
      throw new Error(`Cycle detected involving task: ${name}`);
    }
    if (completed.has(name)) {
      return false;
    }
    inProgress.add(name);
    const deps = graph[name];
    for (const dep of deps) {
      if (detectCycle(dep)) {
        throw new Error(`Cycle detected involving task: ${name}`);
      }
    }
    inProgress.delete(name);
    return false;
  }

