export type PickType<T, K extends keyof T> = {
  [P in K]: T[P]
};

export type OmitType<T, K extends keyof T> = {
  [P in Exclude<keyof T, K>]: T[P]
};

export function pick<T extends object, K extends keyof T>(
  obj: T,
  keys: readonly [...K]
): PickType<T, K> {
  const result: any = {};
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      result[key] = obj[key];
    }
  }
  return result as PickType<T, K>;
}

export function omit<T extends object, K extends keyof T>(
  obj: T,
  keys: readonly [...K]
): OmitType<T, K> {
  const result: any = {};
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key) && !keys.includes(key as K)) {
      result[key] = obj[key];
    }
  }
  return result as OmitType<T, K>;
}

